import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import Menu from './components/Menu';
import Features from './components/Features';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import './styles.css';

function App() {
  const [cartItems, setCartItems] = useState([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  useEffect(() => {
    const storedCart = localStorage.getItem('flavorverseCart');
    if (storedCart) {
      setCartItems(JSON.parse(storedCart));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('flavorverseCart', JSON.stringify(cartItems));
  }, [cartItems]);

  const addToCart = (item) => {
    setCartItems((prevItems) => {
      const existingItemIndex = prevItems.findIndex((i) => i.id === item.id);
      if (existingItemIndex > -1) {
        const updatedItems = [...prevItems];
        updatedItems[existingItemIndex].quantity += item.quantity;
        return updatedItems;
      } else {
        return [...prevItems, { ...item }];
      }
    });
  };

  const updateCartQuantity = (itemId, quantity) => {
    setCartItems((prevItems) => {
      if (quantity <= 0) {
        return prevItems.filter((item) => item.id !== itemId);
      }
      return prevItems.map((item) =>
        item.id === itemId ? { ...item, quantity: quantity } : item
      );
    });
  };

  const removeFromCart = (itemId) => {
    setCartItems((prevItems) => prevItems.filter((item) => item.id !== itemId));
  };

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => total + item.price * item.quantity, 0).toFixed(2);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-amber-100 font-sans text-gray-800">
      <Header cartItemCount={cartItems.reduce((acc, item) => acc + item.quantity, 0)} onCartClick={() => setIsCartOpen(true)} />
      <main>
        <Hero />
        <Menu addToCart={addToCart} />
        <Features />
        <Testimonials />
      </main>
      <Footer />

      {/* Cart Modal */}
      {isCartOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg p-6 md:p-8 relative max-h-[90vh] overflow-y-auto">
            <h2 className="text-3xl font-extrabold text-amber-800 mb-6 border-b-2 border-amber-200 pb-3 flex items-center justify-between">
              Your Cart 🛒
              <button
                onClick={() => setIsCartOpen(false)}
                className="text-gray-500 hover:text-gray-900 transition-colors duration-200 text-4xl leading-none"
              >
                &times;
              </button>
            </h2>
            {cartItems.length === 0 ? (
              <p className="text-gray-600 text-lg text-center py-8">Your cart is empty. Time to fill it with deliciousness! 😋</p>
            ) : (
              <div>
                <ul className="space-y-4 mb-6">
                  {cartItems.map((item) => (
                    <li key={item.id} className="flex items-center justify-between bg-amber-50 p-4 rounded-xl shadow-sm">
                      <div className="flex-1 pr-4">
                        <h3 className="font-semibold text-lg text-amber-900">{item.name}</h3>
                        <p className="text-sm text-gray-600">${item.price.toFixed(2)} each</p>
                      </div>
                      <div className="flex items-center space-x-2">
                        <button
                          onClick={() => updateCartQuantity(item.id, item.quantity - 1)}
                          className="bg-amber-200 hover:bg-amber-300 text-amber-900 font-bold py-1 px-3 rounded-full transition-all duration-200 text-lg"
                        >
                          -
                        </button>
                        <span className="font-bold text-lg w-8 text-center">{item.quantity}</span>
                        <button
                          onClick={() => updateCartQuantity(item.id, item.quantity + 1)}
                          className="bg-amber-200 hover:bg-amber-300 text-amber-900 font-bold py-1 px-3 rounded-full transition-all duration-200 text-lg"
                        >
                          +
                        </button>
                        <button
                          onClick={() => removeFromCart(item.id)}
                          className="ml-3 text-red-500 hover:text-red-700 transition-colors duration-200 text-2xl"
                        >
                          &times;
                        </button>
                      </div>
                    </li>
                  ))}
                </ul>
                <div className="flex justify-between items-center text-2xl font-bold text-amber-900 pt-4 border-t-2 border-amber-200">
                  <span>Total:</span>
                  <span>${calculateTotal()}</span>
                </div>
                <button className="mt-8 w-full bg-amber-600 hover:bg-amber-700 text-white font-extrabold py-4 px-6 rounded-full text-xl shadow-lg transform hover:scale-105 transition-all duration-300 ease-in-out">
                  Proceed to Checkout 🚀
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

